query:
PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?type ?category ?price ?rating
WHERE {
  ?product a ?type ;
           rdfs:label ?name ;
           rt:hasCategory ?cat ;
           rt:price ?price ;
           rt:rating ?rating .
  ?type rdfs:subClassOf* rt:Product .
  ?cat rdfs:label ?category .
  FILTER(?type != rt:Product)
}
ORDER BY ?category ?name

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?subcategory ?price ?rating ?inStock
WHERE {
  ?product rt:hasCategory rt:PCComponents ;
           rdfs:label ?name ;
           rt:hasSubcategory ?subcat ;
           rt:price ?price ;
           rt:rating ?rating ;
           rt:inStock ?inStock .
  ?subcat rdfs:label ?subcategory .
}
ORDER BY ?subcategory ?price

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?price ?vram ?tdp ?tier ?minPSU ?gpuLength
WHERE {
  ?gpu a rt:GPU ;
       rdfs:label ?name ;
       rt:price ?price ;
       rt:vram ?vram ;
       rt:tdp ?tdp ;
       rt:minPSUWattage ?minPSU ;
       rt:gpuLength ?gpuLength ;
       rt:hasPerformanceTier ?tierNode .
  ?tierNode rdfs:label ?tier .
}
ORDER BY ?price

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cpuName ?socketLabel ?mbName ?mbPrice ?ramType ?formFactor
WHERE {
  ?cpu a rt:CPU ;
       rdfs:label ?cpuName ;
       rt:hasSocket ?socket .
  ?socket rdfs:label ?socketLabel .
  ?mb a rt:Motherboard ;
      rdfs:label ?mbName ;
      rt:price ?mbPrice ;
      rt:hasSocket ?socket ;
      rt:hasRAMType ?ramTypeNode ;
      rt:hasFormFactor ?ffNode .
  ?ramTypeNode rdfs:label ?ramType .
  ?ffNode rdfs:label ?formFactor .
  FILTER(?cpuName = "AMD Ryzen 7 7800X3D")
}

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?mbName ?ramTypeName ?ramName ?ramPrice ?ramSpeed ?ramCapacity ?modules
WHERE {
  ?mb a rt:Motherboard ;
      rdfs:label ?mbName ;
      rt:hasRAMType ?ramType .
  ?ramType rdfs:label ?ramTypeName .
  ?ram a rt:RAM ;
       rdfs:label ?ramName ;
       rt:price ?ramPrice ;
       rt:hasRAMType ?ramType ;
       rt:ramSpeed ?ramSpeed ;
       rt:ramCapacity ?ramCapacity ;
       rt:ramModules ?modules .
  FILTER(?mbName = "ASUS TUF Gaming B650-PLUS")
}

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?gpuName ?gpuLen ?caseName ?maxLen ?casePrice
WHERE {
  ?gpu a rt:GPU ;
       rdfs:label ?gpuName ;
       rt:gpuLength ?gpuLen .
  ?case a rt:Case ;
        rdfs:label ?caseName ;
        rt:maxGPULength ?maxLen ;
        rt:price ?casePrice .
  FILTER(?maxLen >= ?gpuLen)
}
ORDER BY ?gpuName ?casePrice

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cpuName ?gpuName ?totalTDP ?psuName ?psuWattage ?headroom ?efficiency
WHERE {
  ?cpu a rt:CPU ;
       rdfs:label ?cpuName ;
       rt:tdp ?cpuTDP .
  ?gpu a rt:GPU ;
       rdfs:label ?gpuName ;
       rt:tdp ?gpuTDP .
  BIND(?cpuTDP + ?gpuTDP AS ?totalTDP)
  ?psu a rt:PSU ;
       rdfs:label ?psuName ;
       rt:psuWattage ?psuWattage ;
       rt:hasEfficiencyRating ?effNode .
  ?effNode rdfs:label ?efficiency .
  FILTER(?psuWattage >= ?totalTDP)
  BIND(?psuWattage - ?totalTDP AS ?headroom)
}
ORDER BY ?cpuName ?gpuName ?psuWattage

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cpuName ?cpuScore ?gpuName ?gpuScore ?scoreDiff
WHERE {
  ?cpu a rt:CPU ;
       rdfs:label ?cpuName ;
       rt:performanceScore ?cpuScore .
  ?gpu a rt:GPU ;
       rdfs:label ?gpuName ;
       rt:performanceScore ?gpuScore .
  BIND(ABS(?cpuScore - ?gpuScore) AS ?scoreDiff)
}
ORDER BY ?scoreDiff

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?price ?originalPrice ?savings
WHERE {
  ?product rdfs:label ?name ;
           rt:price ?price ;
           rt:originalPrice ?originalPrice .
  FILTER(?originalPrice > ?price)
  BIND(?originalPrice - ?price AS ?savings)
}
ORDER BY DESC(?savings)

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?price ?rating ?reviewCount ?category
WHERE {
  ?product rdfs:label ?name ;
           rt:price ?price ;
           rt:rating ?rating ;
           rt:reviewCount ?reviewCount ;
           rt:giftSuitability "high" ;
           rt:hasCategory ?cat .
  ?cat rdfs:label ?category .
  FILTER(?price <= 100)
}
ORDER BY DESC(?rating)

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?productName ?relationship ?relatedName
WHERE {
  {
    ?product rt:alternativeTo ?related .
    BIND("alternative to" AS ?relationship)
  } UNION {
    ?product rt:worksWellWith ?related .
    BIND("works well with" AS ?relationship)
  } UNION {
    ?product rt:isConsumableFor ?related .
    BIND("consumable for" AS ?relationship)
  }
  ?product rdfs:label ?productName .
  ?related rdfs:label ?relatedName .
}
ORDER BY ?productName ?relationship

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cpuName ?mbName ?ramName ?socket ?ramType ?totalPrice
WHERE {
  ?cpu a rt:CPU ;
       rdfs:label ?cpuName ;
       rt:hasSocket ?socket ;
       rt:price ?cpuPrice .
  ?mb a rt:Motherboard ;
      rdfs:label ?mbName ;
      rt:hasSocket ?socket ;
      rt:hasRAMType ?ramTypeNode ;
      rt:price ?mbPrice .
  ?ram a rt:RAM ;
       rdfs:label ?ramName ;
       rt:hasRAMType ?ramTypeNode ;
       rt:price ?ramPrice .
  ?socket rdfs:label ?socketLabel .
  ?ramTypeNode rdfs:label ?ramType .
  BIND(?cpuPrice + ?mbPrice + ?ramPrice AS ?totalPrice)
  BIND(?socketLabel AS ?socket)
}
ORDER BY ?totalPrice

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?subcategory ?name ?price ?rating ?type
WHERE {
  ?product rt:hasCategory rt:OutdoorGear ;
           rdfs:label ?name ;
           rt:hasSubcategory ?subcat ;
           rt:price ?price ;
           rt:rating ?rating ;
           a ?type .
  ?subcat rdfs:label ?subcategory .
  FILTER(?type IN (rt:GearItem, rt:Consumable))
}
ORDER BY ?subcategory ?price

PREFIX rt: <http://trustgraph.ai/ontology/retail#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?severity ?rule ?message
WHERE {
  ?constraint a ?type ;
              rdfs:label ?name ;
              rt:constraintRule ?rule .
  ?type rdfs:subClassOf rt:CompatibilityConstraint .
  OPTIONAL { ?constraint rt:errorMessage ?errMsg }
  OPTIONAL { ?constraint rt:warningMessage ?warnMsg }
  BIND(IF(?type = rt:HardConstraint, "hard", "soft") AS ?severity)
  BIND(COALESCE(?errMsg, ?warnMsg) AS ?message)
}
ORDER BY ?severity ?name
